import React, { useEffect, useState } from 'react'
import { BarChart3, Boxes, Building2, CalendarDays, ChevronRight, CircleHelp, Database, FileText, Home, LockKeyhole, Moon, Package, Settings, ShoppingCart, Sun, Wallet } from 'lucide-react'
const nav=[['Overview',Home],['Invoices',FileText],['Sales',ShoppingCart],['Purchases',Wallet],['Expenses & Income',Wallet],['Customers',Building2],['Products & Stock',Boxes],['Warehouse',Package],['Reports',BarChart3],['Company Settings',Settings],['Financial Year & GST',CalendarDays],['Data Backup',Database]]
function DataWorkspace({type}) {
 const isCustomers = type === 'customers'
 const api = typeof window !== 'undefined' ? window.tradexo?.database : null
 const [items,setItems] = useState([])
 const [loading,setLoading] = useState(true)
 const [saving,setSaving] = useState(false)
 const [error,setError] = useState('')
 const [notice,setNotice] = useState('')
 const [form,setForm] = useState({name:'',phone:'',email:'',address:'',sku:'',barcode:'',hsnSac:'',defaultTaxRate:'0',lowStockThreshold:'0',unit:'pcs',sellingPrice:'0',openingStock:'0'})
 async function load() {
  if (!api) { setLoading(false); return }
  setLoading(true); setError('')
  try { setItems(isCustomers ? await api.listCustomers() : await api.listProducts()) }
  catch (e) { setError(e.message || 'Could not load local records.') }
  finally { setLoading(false) }
 }
 useEffect(()=>{ load() },[type])
 function update(key,value) { setForm(current=>({...current,[key]:value})) }
 async function submit(e) {
  e.preventDefault(); if (!api) return
  setSaving(true); setError(''); setNotice('')
  try {
   if (isCustomers) await api.createCustomer({name:form.name,phone:form.phone,email:form.email,address:form.address})
   else await api.createProduct({name:form.name,sku:form.sku,barcode:form.barcode,hsnSac:form.hsnSac,defaultTaxRate:form.defaultTaxRate,lowStockThreshold:form.lowStockThreshold,unit:form.unit,sellingPrice:form.sellingPrice,openingStock:form.openingStock})
   setForm({name:'',phone:'',email:'',address:'',sku:'',barcode:'',hsnSac:'',defaultTaxRate:'0',lowStockThreshold:'0',unit:'pcs',sellingPrice:'0',openingStock:'0'})
   setNotice(isCustomers ? 'Customer saved on this PC.' : 'Product saved on this PC.')
   await load()
  } catch (e) { setError(e.message || 'Could not save this record.') }
  finally { setSaving(false) }
 }
 const field = (key,label,placeholder=label,type='text') => <label className="db-field">{label}<input required={key==='name'} type={type} value={form[key]} placeholder={placeholder} onChange={e=>update(key,e.target.value)}/></label>
 return <div className="db-workspace">
  <div className="db-heading"><div><h2>{isCustomers?'Customers':'Products & Stock'}</h2><p>{isCustomers?'Save customer contact details locally on this computer.':'Create your local product catalogue and opening stock.'}</p></div><span className="db-count">{items.length} records</span></div>
  {!api ? <div className="panel db-empty"><LockKeyhole/><b>Open the TRADEXO Windows desktop app</b><p>Local database access is available inside the Electron desktop app, not the browser preview.</p></div> : <>
   <form className="panel db-form" onSubmit={submit}><div className="panel-title"><b>{isCustomers?'Add customer':'Add product'}</b><span>Saved locally</span></div>
    <div className="db-fields">{field('name',isCustomers?'Customer name':'Product name')}
     {isCustomers ? <>{field('phone','Phone number','Optional phone','tel')}{field('email','Email','Optional email','email')}{field('address','Address','Optional address')}</> : <>{field('sku','SKU / Code','Optional SKU')}{field('barcode','Barcode','Optional barcode')}{field('hsnSac','HSN / SAC code','2, 4, 6 or 8 digits')}{field('defaultTaxRate','Default GST rate (%)','0','number')}{field('lowStockThreshold','Low-stock alert at quantity','0','number')}{field('unit','Unit','pcs')}{field('sellingPrice','Selling price','0','number')}{field('openingStock','Opening stock','0','number')}</>}
    </div>
    {error&&<p className="db-error">{error}</p>}{notice&&<p className="db-success">{notice}</p>}
    <button className="db-save" disabled={saving}>{saving?'Saving…':isCustomers?'Save customer':'Save product'}</button>
   </form>
   <div className="panel db-list"><div className="panel-title"><b>{isCustomers?'Customer records':'Product records'}</b><button type="button" className="db-refresh" onClick={load}>Refresh</button></div>
    {loading?<p className="db-muted">Loading records…</p>:items.length===0?<p className="db-muted">No records yet. Add your first {isCustomers?'customer':'product'} above.</p>:
     <div className="db-table-wrap"><table><thead><tr>{(isCustomers?['Name','Phone','Email','Address','Created']:['Product','SKU','Barcode','HSN / SAC','Default GST %','Unit','Selling price','Opening stock','Low-stock alert']).map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{items.map(item=><tr key={item.id}>{(isCustomers?[item.name,item.phone,item.email,item.address,item.created_at?.slice(0,10)]:[item.name,item.sku,item.barcode,item.hsn_sac,item.default_tax_rate,item.unit,'₹'+Number(item.selling_price).toFixed(2),item.opening_stock,item.low_stock_threshold]).map((v,i)=><td key={i}>{v||'—'}</td>)}</tr>)}</tbody></table></div>}
   </div>
  </>}
 </div>
}
function TradeWorkspace({type='sales'}){
 const api=typeof window!=='undefined'?window.tradexo?.database:null,sales=type==='sales'
 const [party,setParty]=useState([]),[products,setProducts]=useState([]),[docs,setDocs]=useState([]),[years,setYears]=useState([]),[taxSettings,setTaxSettings]=useState({gst_enabled:0,default_tax_mode:'none'}),[gstins,setGstins]=useState([])
 const [selectedInvoice,setSelectedInvoice]=useState(null),[printInvoice,setPrintInvoice]=useState(null),[receipts,setReceipts]=useState([]),[receiptNumber,setReceiptNumber]=useState(''),[receiptDate,setReceiptDate]=useState(new Date().toISOString().slice(0,10)),[receiptAmount,setReceiptAmount]=useState(''),[receiptMethod,setReceiptMethod]=useState('upi'),[receiptReference,setReceiptReference]=useState('')
 const [selectedPurchase,setSelectedPurchase]=useState(null),[supplierPayments,setSupplierPayments]=useState([]),[supplierPaymentNumber,setSupplierPaymentNumber]=useState(''),[supplierPaymentDate,setSupplierPaymentDate]=useState(new Date().toISOString().slice(0,10)),[supplierPaymentAmount,setSupplierPaymentAmount]=useState(''),[supplierPaymentMethod,setSupplierPaymentMethod]=useState('upi'),[supplierPaymentReference,setSupplierPaymentReference]=useState('')
 const [partyId,setPartyId]=useState(''),[number,setNumber]=useState(''),[date,setDate]=useState(new Date().toISOString().slice(0,10)),[items,setItems]=useState([{productId:'',quantity:'1',price:'0',taxRate:'0'}]),[vendorName,setVendorName]=useState(''),[vendorGstin,setVendorGstin]=useState(''),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false)
 async function load(){if(!api)return;const v=await Promise.all([sales?api.listCustomers():api.listVendors(),api.listProducts(),sales?api.listSalesInvoices():api.listPurchaseBills(),api.listFinancialYears(),api.getCompanyTaxSettings(),api.listCompanyGstins()]);setParty(v[0]);setProducts(v[1]);setDocs(v[2]);setYears(v[3]);setTaxSettings(v[4]||{gst_enabled:0,default_tax_mode:'none'});setGstins(v[5]||[]);if(!partyId&&v[0][0])setPartyId(v[0][0].id);if(!items[0].productId&&v[1][0])setItems([{productId:v[1][0].id,quantity:'1',price:String(sales?v[1][0].selling_price:0),taxRate:String(v[1][0].default_tax_rate||0)}])}
 useEffect(()=>{load().catch(e=>setError(e.message||'Could not load records.'))},[type])
 useEffect(()=>{if(!printInvoice)return;const timer=setTimeout(()=>window.print(),180);const close=()=>setPrintInvoice(null);window.addEventListener('afterprint',close);return()=>{clearTimeout(timer);window.removeEventListener('afterprint',close)}},[printInvoice])
 function change(i,k,v){setItems(old=>old.map((x,n)=>n===i?{...x,[k]:v}:x))}
 async function save(e){e.preventDefault();setBusy(true);setError('');try{const p=sales?{customerId:partyId,invoiceNumber:number,invoiceDate:date,items:items.map(x=>({productId:x.productId,quantity:x.quantity,unitPrice:x.price,taxRate:x.taxRate}))}:{vendorId:partyId,billNumber:number,billDate:date,items:items.map(x=>({productId:x.productId,quantity:x.quantity,unitCost:x.price,taxRate:x.taxRate}))};if(sales)await api.createSalesInvoiceDraft(p);else await api.createPurchaseBillDraft(p);setNumber('');setNotice('Draft saved. Stock changes only after posting.');await load()}catch(e){setError(e.message||'Could not save.')}finally{setBusy(false)}}
 async function post(id){setBusy(true);setError('');try{if(sales)await api.postSalesInvoice(id);else await api.postPurchaseBill(id);await load();setNotice('Posted. Stock ledger updated.')}catch(e){setError(e.message||'Could not post.')}finally{setBusy(false)}}
 async function reverse(id){
  const reason=window.prompt('Enter the reason for reversing this posted document:')
  if(!reason||!reason.trim())return
  setBusy(true);setError('');setNotice('')
  try{if(sales)await api.reverseSalesInvoice(id,reason);else await api.reversePurchaseBill(id,reason);await load();setNotice('Reversal saved as a compensating stock movement.')}
  catch(e){setError(e.message||'Could not reverse document.')}finally{setBusy(false)}
 }
 async function addVendor(e){e.preventDefault();setBusy(true);try{const v=await api.createVendor({name:vendorName,gstin:vendorGstin});setVendorName('');setVendorGstin('');await load();setPartyId(v.id);setNotice('Vendor saved.')}catch(e){setError(e.message||'Could not add vendor.')}finally{setBusy(false)}}
 async function openPrintInvoice(invoice){setError('');try{const detail=await api.getSalesInvoice(invoice.id);if(!detail)throw new Error('Invoice was not found.');setPrintInvoice(detail)}catch(e){setError(e.message||'Could not prepare invoice printout.')}}
 async function openReceipt(invoice){setError('');setNotice('');try{const detail=await api.getSalesInvoice(invoice.id);setSelectedInvoice(detail);setReceipts(await api.listSalesReceipts(invoice.id));setReceiptAmount(String(detail.outstanding_amount||''));setReceiptNumber('RCP-'+Date.now().toString().slice(-8));setReceiptDate(new Date().toISOString().slice(0,10));}catch(e){setError(e.message||'Could not load invoice receipts.')}}
 async function saveReceipt(e){e.preventDefault();if(!selectedInvoice)return;setBusy(true);setError('');setNotice('');try{await api.recordSalesReceipt({invoiceId:selectedInvoice.id,receiptNumber,receiptDate,amount:receiptAmount,paymentMethod:receiptMethod,reference:receiptReference});await load();const detail=await api.getSalesInvoice(selectedInvoice.id);setSelectedInvoice(detail);setReceipts(await api.listSalesReceipts(detail.id));setReceiptAmount(String(detail.outstanding_amount||''));setReceiptNumber('RCP-'+Date.now().toString().slice(-8));setReceiptReference('');setNotice('Payment receipt saved permanently. Invoice balance updated.')}catch(e){setError(e.message||'Could not save receipt.')}finally{setBusy(false)}}
 async function openSupplierPayment(bill){setError('');setNotice('');try{const detail=await api.getPurchaseBill(bill.id);setSelectedPurchase(detail);setSupplierPayments(await api.listPurchasePayments(bill.id));setSupplierPaymentAmount(String(detail.outstanding_amount||''));setSupplierPaymentNumber('PAY-'+Date.now().toString().slice(-8));setSupplierPaymentDate(new Date().toISOString().slice(0,10));}catch(e){setError(e.message||'Could not load supplier payment history.')}}
 async function saveSupplierPayment(e){e.preventDefault();if(!selectedPurchase)return;setBusy(true);setError('');setNotice('');try{await api.recordPurchasePayment({billId:selectedPurchase.id,paymentNumber:supplierPaymentNumber,paymentDate:supplierPaymentDate,amount:supplierPaymentAmount,paymentMethod:supplierPaymentMethod,reference:supplierPaymentReference});await load();const detail=await api.getPurchaseBill(selectedPurchase.id);setSelectedPurchase(detail);setSupplierPayments(await api.listPurchasePayments(detail.id));setSupplierPaymentAmount(String(detail.outstanding_amount||''));setSupplierPaymentNumber('PAY-'+Date.now().toString().slice(-8));setSupplierPaymentReference('');setNotice('Supplier payment saved permanently. Payable balance updated.')}catch(e){setError(e.message||'Could not save supplier payment.')}finally{setBusy(false)}}
 if(!api)return <div className="panel db-empty"><LockKeyhole/><b>Open TRADEXO desktop app</b><p>Transaction records are saved locally.</p></div>
 const fy=years.find(x=>x.status==='active'),sellerGstin=gstins.find(x=>x.id===taxSettings.default_gstin_id),supplier=party.find(x=>x.id===partyId),placeState=taxSettings.place_of_supply_state_code||sellerGstin?.state_code,supplyType=sales?(sellerGstin&&placeState?(sellerGstin.state_code===placeState?'intra':'inter'):'intra'):(supplier?.state_code&&placeState?(supplier.state_code===placeState?'intra':'inter'):'intra'),gstApplies=taxSettings.gst_enabled===1&&(sales||Boolean(supplier?.gstin)),taxMode=gstApplies?taxSettings.default_tax_mode:'none',taxPreview=items.reduce((acc,x)=>{const entered=Math.round((Number(x.quantity)||0)*(Number(x.price)||0)*100),rate=gstApplies?(Number(x.taxRate)||0):0;let taxable=entered,tax=0;if(taxMode==='exclusive')tax=Math.round(entered*rate/100);else if(taxMode==='inclusive'&&rate>0){taxable=Math.round(entered*100/(100+rate));tax=entered-taxable}acc.taxable+=taxable;acc.tax+=tax;if(supplyType==='inter')acc.igst+=tax;else{acc.cgst+=Math.floor(tax/2);acc.sgst+=tax-Math.floor(tax/2)}return acc},{taxable:0,tax:0,cgst:0,sgst:0,igst:0}),total=(taxPreview.taxable+taxPreview.tax)/100
 return <div className="db-workspace"><div className="db-heading"><div><h2>{sales?'Sales invoices':'Purchase bills'}</h2><p>{sales?'Customer billing and stock-out posting.':'Supplier bills and stock-in posting.'}</p></div><span className="db-count">{docs.length} records</span></div>
 <div className="panel db-list"><div className="panel-title"><b>Active financial year</b><span>{fy?.label||'Not configured'}</span></div>{!fy&&<p className="db-error">Create and activate a financial year first.</p>}</div>
 {!sales&&<form className="panel db-form" onSubmit={addVendor}><div className="panel-title"><b>Add vendor</b></div><div className="db-fields"><label className="db-field">Vendor name<input required value={vendorName} onChange={e=>setVendorName(e.target.value)}/></label><label className="db-field">Vendor GSTIN (optional)<input maxLength={15} value={vendorGstin} onChange={e=>setVendorGstin(e.target.value.toUpperCase())} placeholder="08ABCDE1234F1Z5"/></label></div><button className="db-save" disabled={busy}>Save vendor</button></form>}
 <form className="panel db-form" onSubmit={save}><div className="panel-title"><b>{sales?'New invoice draft':'New purchase draft'}</b><span>Draft does not change stock</span></div>
 <div className="db-fields"><label className="db-field">{sales?'Customer':'Vendor'}<select required value={partyId} onChange={e=>setPartyId(e.target.value)}><option value="">Select</option>{party.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label className="db-field">Document number<input required value={number} onChange={e=>setNumber(e.target.value)} maxLength={50}/></label><label className="db-field">Document date<input type="date" required value={date} onChange={e=>setDate(e.target.value)}/></label></div>
 <div className="trade-items"><div className="panel-title"><b>Items</b><button type="button" className="db-refresh" onClick={()=>setItems(x=>[...x,{productId:products[0]?.id||'',quantity:'1',price:'0',taxRate:String(products[0]?.default_tax_rate||0)}])}>+ Add item</button></div>
 {items.map((x,i)=><div className="trade-item" key={i}><label className="db-field">Product<select required value={x.productId} onChange={e=>{const p=products.find(z=>z.id===e.target.value);change(i,'productId',e.target.value);change(i,'price',String(sales?(p?.selling_price||0):0));change(i,'taxRate',String(p?.default_tax_rate||0))}}><option value="">Select product</option>{products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label className="db-field">Quantity<input type="number" min="0.0001" step="any" required value={x.quantity} onChange={e=>change(i,'quantity',e.target.value)}/></label><label className="db-field">{sales?'Unit price':'Unit cost'} ₹<input type="number" min="0" step="0.01" required value={x.price} onChange={e=>change(i,'price',e.target.value)}/></label>{gstApplies&&<label className="db-field">GST rate (%)<input type="number" min="0" max="100" step="0.01" required value={x.taxRate||'0'} onChange={e=>change(i,'taxRate',e.target.value)}/></label>}{items.length>1&&<button type="button" className="db-refresh" onClick={()=>setItems(x=>x.filter((_,n)=>n!==i))}>Remove</button>}</div>)}</div>
 <div className="trade-total"><span>{gstApplies?'Taxable value':'Subtotal'}</span><b>₹{(taxPreview.taxable/100).toFixed(2)}</b></div>{gstApplies&&<div className="db-tax-summary"><span>{supplyType==='inter'?'IGST':'CGST'}: ₹{((taxPreview.igst||taxPreview.cgst)/100).toFixed(2)}</span><span>{supplyType==='intra'?'SGST: ₹'+(taxPreview.sgst/100).toFixed(2):'Place of supply: '+(placeState||'Not set')}</span><small>Tax mode: {taxMode} · {supplyType==='inter'?'Inter-state':'Intra-state'}</small></div>}<div className="trade-total"><span>{sales?'Invoice total':'Purchase total'}</span><b>₹{total.toFixed(2)}</b></div>{error&&<p className="db-error">{error}</p>}{notice&&<p className="db-success">{notice}</p>}<button className="db-save" disabled={busy||!fy||!party.length||!products.length}>Save draft</button></form>
 <div className="panel db-list"><div className="panel-title"><b>{sales?'Invoice register':'Purchase register'}</b><button className="db-refresh" onClick={()=>load()}>Refresh</button></div><div className="db-table-wrap"><table><thead><tr><th>Number</th><th>Party</th><th>Date</th><th>Total</th><th>Status</th><th>Action</th></tr></thead><tbody>{docs.map(d=><tr key={d.id}><td>{sales?d.invoice_number:d.bill_number}</td><td>{sales?d.customer_name:d.vendor_name}</td><td>{sales?d.invoice_date:d.bill_date}</td><td>₹{Number(d.total_amount).toFixed(2)}</td><td>{d.status}{d.status==='posted'?' · '+d.payment_status:''}</td><td>{sales&&<button className="db-refresh" disabled={busy} onClick={()=>openPrintInvoice(d)}>Print / PDF</button>} {d.status==='draft'?<button className="db-refresh" disabled={busy} onClick={()=>post(d.id)}>Post</button>:d.status==='posted'?<>{sales?<button className="db-refresh" disabled={busy} onClick={()=>openReceipt(d)}>Receive payment</button>:<button className="db-refresh" disabled={busy} onClick={()=>openSupplierPayment(d)}>Pay supplier</button>} <button className="db-refresh" disabled={busy} onClick={()=>reverse(d.id)}>Reverse</button></>:'—'}</td></tr>)}</tbody></table></div></div>
 {sales&&selectedInvoice&&<div className="panel db-form"><div className="panel-title"><b>Receive payment · {selectedInvoice.invoice_number}</b><span>Outstanding ₹{Number(selectedInvoice.outstanding_amount||0).toFixed(2)}</span></div>{Number(selectedInvoice.outstanding_amount||0)>0?<form onSubmit={saveReceipt}><div className="db-fields"><label className="db-field">Receipt number<input required maxLength={50} value={receiptNumber} onChange={e=>setReceiptNumber(e.target.value)}/></label><label className="db-field">Payment date<input type="date" required value={receiptDate} onChange={e=>setReceiptDate(e.target.value)}/></label><label className="db-field">Amount received (₹)<input type="number" min="0.01" max={selectedInvoice.outstanding_amount} step="0.01" required value={receiptAmount} onChange={e=>setReceiptAmount(e.target.value)}/></label><label className="db-field">Payment method<select value={receiptMethod} onChange={e=>setReceiptMethod(e.target.value)}><option value="upi">UPI</option><option value="cash">Cash</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option><option value="card">Card</option><option value="other">Other</option></select></label><label className="db-field">Reference / UTR (optional)<input maxLength={100} value={receiptReference} onChange={e=>setReceiptReference(e.target.value)}/></label></div><button className="db-save" disabled={busy}>Save payment receipt</button></form>:<p className="db-success">This invoice is fully paid.</p>}<div className="panel-title" style={{marginTop:18}}><b>Payment history</b><span>{receipts.length} receipts · append-only</span></div>{receipts.length===0?<p className="db-muted">No payment received yet.</p>:<div className="db-table-wrap"><table><thead><tr><th>Receipt</th><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody>{receipts.map(r=><tr key={r.id}><td>{r.receipt_number}</td><td>{r.receipt_date}</td><td>{r.payment_method}</td><td>{r.reference||'—'}</td><td>₹{Number(r.amount).toFixed(2)}</td></tr>)}</tbody></table></div>}<button type="button" className="db-refresh" onClick={()=>setSelectedInvoice(null)}>Close payment panel</button></div>}
 {!sales&&selectedPurchase&&<div className="panel db-form"><div className="panel-title"><b>Pay supplier · {selectedPurchase.bill_number}</b><span>Outstanding ₹{Number(selectedPurchase.outstanding_amount||0).toFixed(2)}</span></div>{Number(selectedPurchase.outstanding_amount||0)>0?<form onSubmit={saveSupplierPayment}><div className="db-fields"><label className="db-field">Payment number<input required maxLength={50} value={supplierPaymentNumber} onChange={e=>setSupplierPaymentNumber(e.target.value)}/></label><label className="db-field">Payment date<input type="date" required value={supplierPaymentDate} onChange={e=>setSupplierPaymentDate(e.target.value)}/></label><label className="db-field">Amount paid (₹)<input type="number" min="0.01" max={selectedPurchase.outstanding_amount} step="0.01" required value={supplierPaymentAmount} onChange={e=>setSupplierPaymentAmount(e.target.value)}/></label><label className="db-field">Payment method<select value={supplierPaymentMethod} onChange={e=>setSupplierPaymentMethod(e.target.value)}><option value="upi">UPI</option><option value="cash">Cash</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option><option value="card">Card</option><option value="other">Other</option></select></label><label className="db-field">Reference / UTR<input maxLength={100} value={supplierPaymentReference} onChange={e=>setSupplierPaymentReference(e.target.value)}/></label></div><button className="db-save" disabled={busy}>Save supplier payment</button></form>:<p className="db-success">This supplier bill is fully paid.</p>}<div className="panel-title" style={{marginTop:18}}><b>Payment history</b><span>{supplierPayments.length} entries · append-only</span></div>{supplierPayments.length===0?<p className="db-muted">No supplier payment recorded yet.</p>:<div className="db-table-wrap"><table><thead><tr><th>Payment</th><th>Date</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody>{supplierPayments.map(p=><tr key={p.id}><td>{p.payment_number}</td><td>{p.payment_date}</td><td>{p.payment_method}</td><td>{p.reference||'—'}</td><td>₹{Number(p.amount).toFixed(2)}</td></tr>)}</tbody></table></div>}<button type="button" className="db-refresh" onClick={()=>setSelectedPurchase(null)}>Close payment panel</button></div>}
 {sales&&printInvoice&&<div className="tradexo-print-overlay"><div className="tradexo-print-toolbar"><b>Invoice preview</b><div><button type="button" className="db-refresh" onClick={()=>window.print()}>Print / Save PDF</button><button type="button" className="db-refresh" onClick={()=>setPrintInvoice(null)}>Close</button></div></div><article className="tradexo-invoice-paper"><header className="tradexo-invoice-header"><div><h1>{printInvoice.business_name||'TRADEXO Business'}</h1>{printInvoice.legal_name&&<p>{printInvoice.legal_name}</p>}{printInvoice.company_address&&<p>{printInvoice.company_address}</p>}{printInvoice.company_phone&&<p>Phone: {printInvoice.company_phone}</p>}{printInvoice.company_email&&<p>Email: {printInvoice.company_email}</p>}{printInvoice.company_website&&<p>{printInvoice.company_website}</p>}<p>Tax Invoice</p></div><div className="tradexo-invoice-meta"><b>INVOICE</b><strong>{printInvoice.invoice_number}</strong><span>Date: {printInvoice.invoice_date}</span><span>Financial year: {printInvoice.financial_year}</span>{printInvoice.due_date&&<span>Due: {printInvoice.due_date}</span>}</div></header><div className="tradexo-invoice-parties"><section><b>Bill To</b><strong>{printInvoice.customer_name}</strong>{printInvoice.customer_address&&<span>{printInvoice.customer_address}</span>}{printInvoice.customer_phone&&<span>Phone: {printInvoice.customer_phone}</span>}{printInvoice.customer_email&&<span>{printInvoice.customer_email}</span>}</section><section><b>Tax details</b>{printInvoice.seller_gstin&&<span>GSTIN: {printInvoice.seller_gstin}</span>}{printInvoice.place_of_supply_state_code&&<span>Place of supply state: {printInvoice.place_of_supply_state_code}</span>}<span>{printInvoice.supply_type==='inter'?'Inter-state supply':'Intra-state supply'}</span></section></div><table className="tradexo-invoice-table"><thead><tr><th>#</th><th>Description</th><th>HSN / SAC</th><th>Qty</th><th>Rate (₹)</th><th>GST %</th><th>Taxable (₹)</th><th>Tax (₹)</th><th>Total (₹)</th></tr></thead><tbody>{(printInvoice.items||[]).map((item,index)=><tr key={item.id}><td>{index+1}</td><td>{item.description}</td><td>{item.hsn_sac||'—'}</td><td>{Number(item.quantity)}</td><td>{Number(item.unit_price).toFixed(2)}</td><td>{Number(item.tax_rate||0).toFixed(2)}%</td><td>{Number(item.taxable_value??item.line_total).toFixed(2)}</td><td>{Number(item.total_tax||0).toFixed(2)}</td><td>{Number(item.line_total).toFixed(2)}</td></tr>)}</tbody></table><div className="tradexo-invoice-bottom"><div className="tradexo-invoice-notes"><b>Payment status: {printInvoice.payment_status||'unpaid'}</b><span>Received: ₹{Number(printInvoice.received_amount||0).toFixed(2)}</span><span>Balance due: ₹{Number(printInvoice.outstanding_amount??printInvoice.total_amount).toFixed(2)}</span><small>Computer-generated invoice. Please verify all details before issuing.</small></div><div className="tradexo-invoice-totals"><div><span>Taxable value</span><b>₹{Number(printInvoice.taxable_value??printInvoice.total_amount).toFixed(2)}</b></div>{Number(printInvoice.cgst||0)>0&&<div><span>CGST</span><b>₹{Number(printInvoice.cgst).toFixed(2)}</b></div>}{Number(printInvoice.sgst||0)>0&&<div><span>SGST</span><b>₹{Number(printInvoice.sgst).toFixed(2)}</b></div>}{Number(printInvoice.igst||0)>0&&<div><span>IGST</span><b>₹{Number(printInvoice.igst).toFixed(2)}</b></div>}<div><span>Total tax</span><b>₹{Number(printInvoice.total_tax||0).toFixed(2)}</b></div><div className="tradexo-invoice-grand"><span>Grand total</span><b>₹{Number(printInvoice.total_amount).toFixed(2)}</b></div></div></div><footer className="tradexo-invoice-footer"><div><span>Thank you for your business.</span>{(printInvoice.bank_name||printInvoice.bank_account_number||printInvoice.bank_ifsc)&&<small>Bank: {printInvoice.bank_name||'—'} · A/c name: {printInvoice.bank_account_name||'—'} · A/c no.: {printInvoice.bank_account_number||'—'} · IFSC: {printInvoice.bank_ifsc||'—'} · Branch: {printInvoice.bank_branch||'—'}</small>}</div><span>Authorised Signatory</span></footer></article></div>}
 <p className="db-muted">Posted documents create permanent stock movements. Reversals add compensating entries. GST amounts are calculated and saved from Company GST settings and each item's selected rate. E-invoice and GST portal filing are not included.</p></div>
}
function ReceivablesAgingWorkspace(){
 const api=typeof window!=='undefined'?window.tradexo?.database:null
 const [invoices,setInvoices]=useState([]),[asOf,setAsOf]=useState(new Date().toISOString().slice(0,10)),[loading,setLoading]=useState(true),[error,setError]=useState('')
 async function load(){if(!api){setLoading(false);return}setLoading(true);setError('');try{setInvoices(await api.listSalesInvoices())}catch(e){setError(e.message||'Could not load invoices.')}finally{setLoading(false)}}
 useEffect(()=>{load()},[])
 const buckets={current:0,days_1_30:0,days_31_60:0,days_61_90:0,days_over_90:0}
 let outstandingTotal=0
 for(const invoice of invoices){
  if(invoice.status!=='posted')continue
  const total=Math.round(Number(invoice.total_amount||0)*100),received=Math.round(Number(invoice.received_amount||0)*100),outstanding=Math.max(0,total-received)
  if(!Number.isFinite(outstanding)||outstanding===0)continue
  const due=invoice.due_date||invoice.invoice_date
  if(!due)continue
  const days=Math.floor((Date.parse(asOf+'T00:00:00Z')-Date.parse(due+'T00:00:00Z'))/86400000)
  const key=days<=0?'current':days<=30?'days_1_30':days<=60?'days_31_60':days<=90?'days_61_90':'days_over_90'
  buckets[key]+=outstanding;outstandingTotal+=outstanding
 }
 const money=v=>'₹'+(v/100).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})
 if(!api)return <div className="panel db-empty"><LockKeyhole/><b>Open TRADEXO desktop app</b><p>Receivables report reads local invoice records.</p></div>
 return <div className="db-workspace"><div className="db-heading"><div><h2>Receivables Aging</h2><p>Outstanding invoice balances grouped by due date. As-of date can be changed.</p></div><span className="db-count">{invoices.length} invoices</span></div>
 <div className="panel db-form"><div className="db-fields"><label className="db-field">Report as of<input type="date" value={asOf} onChange={e=>setAsOf(e.target.value)}/></label></div><button type="button" className="db-refresh" onClick={load}>Refresh invoices</button>{error&&<p className="db-error">{error}</p>}</div>
 <div className="stats aging-stats"><div><small>Total outstanding</small><b>{money(outstandingTotal)}</b><em>Based on recorded receipts</em></div><div><small>Current / not overdue</small><b>{money(buckets.current)}</b></div><div><small>1–30 days</small><b>{money(buckets.days_1_30)}</b></div><div><small>31–60 days</small><b>{money(buckets.days_31_60)}</b></div></div>
 <div className="panel db-list"><div className="panel-title"><b>Aging buckets</b><span>{loading?'Loading…':'Live local calculation'}</span></div><div className="db-table-wrap"><table><thead><tr><th>Age</th><th>Outstanding</th></tr></thead><tbody>{[['Current',buckets.current],['1–30 days',buckets.days_1_30],['31–60 days',buckets.days_31_60],['61–90 days',buckets.days_61_90],['Over 90 days',buckets.days_over_90]].map(([label,value])=><tr key={label}><td>{label}</td><td>{money(value)}</td></tr>)}</tbody></table></div></div>
 <p className="db-muted">Only posted invoices are included. Received amounts are calculated from the permanent receipt ledger; fully paid invoices are excluded from outstanding buckets. Review source invoices before statutory or collection decisions.</p></div>
}

function FinancialEntriesWorkspace(){
 const api=typeof window!=='undefined'?window.tradexo?.database:null
 const [entries,setEntries]=useState([]),[summary,setSummary]=useState({income_total:0,expense_total:0,net_total:0})
 const [entryType,setEntryType]=useState('expense'),[entryNumber,setEntryNumber]=useState('EXP-'+Date.now().toString().slice(-8)),[entryDate,setEntryDate]=useState(new Date().toISOString().slice(0,10))
 const [category,setCategory]=useState('Office'),[partyName,setPartyName]=useState(''),[description,setDescription]=useState(''),[amount,setAmount]=useState(''),[paymentMethod,setPaymentMethod]=useState('cash'),[reference,setReference]=useState('')
 const [error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false)
 async function load(){if(!api)return;const [rows,totals]=await Promise.all([api.listFinancialEntries(null,300),api.getFinancialEntrySummary()]);setEntries(rows);setSummary(totals)}
 useEffect(()=>{load().catch(e=>setError(e.message||'Could not load expense and income records.'))},[])
 function changeType(type){setEntryType(type);setEntryNumber((type==='expense'?'EXP-':'INC-')+Date.now().toString().slice(-8))}
 async function save(e){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api.createFinancialEntry({entryType,entryNumber,entryDate,category,partyName,description,amount,paymentMethod,reference});await load();setEntryNumber((entryType==='expense'?'EXP-':'INC-')+Date.now().toString().slice(-8));setDescription('');setPartyName('');setAmount('');setReference('');setNotice('Entry saved permanently in the local ledger.')}catch(e){setError(e.message||'Could not save entry.')}finally{setBusy(false)}}
 const money=v=>'₹'+Number(v||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2})
 if(!api)return <div className="panel db-empty"><LockKeyhole/><b>Open TRADEXO desktop app</b><p>Expenses and other income are stored in the local ledger.</p></div>
 return <div className="db-workspace"><div className="db-heading"><div><h2>Expenses &amp; Indirect Income</h2><p>Record operating expenses and non-sales income against the active financial year.</p></div><span className="db-count">{entries.length} entries</span></div>
 <div className="stats aging-stats"><div><small>Indirect income</small><b>{money(summary.income_total)}</b></div><div><small>Expenses</small><b>{money(summary.expense_total)}</b></div><div><small>Net entries</small><b>{money(summary.net_total)}</b><em>Income minus expenses · not a full P&amp;L</em></div></div>
 <form className="panel db-form" onSubmit={save}><div className="panel-title"><b>New ledger entry</b><span>Entries are permanent; corrections use a separate adjustment later</span></div>
 <div className="db-fields"><label className="db-field">Entry type<select value={entryType} onChange={e=>changeType(e.target.value)}><option value="expense">Expense</option><option value="income">Indirect income</option></select></label>
 <label className="db-field">Entry number<input required maxLength={50} value={entryNumber} onChange={e=>setEntryNumber(e.target.value)}/></label>
 <label className="db-field">Date<input type="date" required value={entryDate} onChange={e=>setEntryDate(e.target.value)}/></label>
 <label className="db-field">Category<input required maxLength={80} value={category} onChange={e=>setCategory(e.target.value)} placeholder="Rent, salary, commission…"/></label>
 <label className="db-field">Party / Payee<input maxLength={120} value={partyName} onChange={e=>setPartyName(e.target.value)}/></label>
 <label className="db-field">Amount (₹)<input type="number" min="0.01" step="0.01" required value={amount} onChange={e=>setAmount(e.target.value)}/></label>
 <label className="db-field">Payment method<select value={paymentMethod} onChange={e=>setPaymentMethod(e.target.value)}><option value="cash">Cash</option><option value="upi">UPI</option><option value="bank_transfer">Bank transfer</option><option value="cheque">Cheque</option><option value="card">Card</option><option value="other">Other</option></select></label>
 <label className="db-field">Reference<input maxLength={100} value={reference} onChange={e=>setReference(e.target.value)}/></label>
 <label className="db-field">Description<input required maxLength={300} value={description} onChange={e=>setDescription(e.target.value)}/></label></div>
 {error&&<p className="db-error">{error}</p>}{notice&&<p className="db-success">{notice}</p>}<button className="db-save" disabled={busy}>{busy?'Saving…':'Save ledger entry'}</button></form>
 <div className="panel db-list"><div className="panel-title"><b>Financial entries</b><button className="db-refresh" type="button" onClick={()=>load()}>Refresh</button></div>
 {entries.length===0?<p className="db-muted">No expenses or indirect income recorded yet.</p>:<div className="db-table-wrap"><table><thead><tr><th>Type</th><th>Number</th><th>Date</th><th>Category</th><th>Party</th><th>Description</th><th>Method</th><th>Amount</th></tr></thead><tbody>{entries.map(row=><tr key={row.id}><td>{row.entry_type}</td><td>{row.entry_number}</td><td>{row.entry_date}</td><td>{row.category}</td><td>{row.party_name||'—'}</td><td>{row.description}</td><td>{row.payment_method}</td><td>{money(row.amount)}</td></tr>)}</tbody></table></div>}</div>
 <p className="db-muted">Entries are company- and financial-year-scoped, append-only and included in encrypted backups. This summary is not a statutory profit-and-loss statement.</p></div>
}

