 async function addCompany(e){e.preventDefault();setBusy(true);setError('');setNotice('');try{const c=await api.createCompany({businessName,legalName});await api.setActiveCompany(c.id);setBusinessName('');setLegalName('');await load();setNotice('Company created and selected. Add its business details below.')}catch(e){setError(e.message||'Could not create company.')}finally{setBusy(false)}}
