 async function saveProfile(e){e.preventDefault();setBusy(true);setError('');setNotice('');try{await api.updateCompanyProfile(profile);await load();setNotice('Company profile saved locally.')}catch(e){setError(e.message||'Could not save company profile.')}finally{setBusy(false)}}
 const setField=(key,value)=>setProfile(old=>({...old,[key]:value}))
